import std.io

interface Holder {
    fn held(self) -> Int64
}
record Wrap<T> { value: T }
impl<T> Holder for Wrap<T> {
    fn held(self) -> Int64 {
        return 0
    }
}
pub type AppError = Failed(String)
pub fn main() effect io -> Result<(), AppError> {
    let w = Wrap { value: 1 }
    let n = w.held()
    io.println("${w.value}${n}")
    return Ok(())
}
